# convex hull and row fill by hull intersections
pts=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==6]
def cross(o,a,b): return (a[0]-o[0])*(b[1]-o[1])-(a[1]-o[1])*(b[0]-o[0])
def hull(P):
 P=sorted(set(P)); lo=[]
 for p in P:
  while len(lo)>1 and cross(lo[-2],lo[-1],p)<=0: lo.pop()
  lo.append(p)
 up=[]
 for p in P[::-1]:
  while len(up)>1 and cross(up[-2],up[-1],p)<=0: up.pop()
  up.append(p)
 return lo[:-1]+up[:-1]
